<?php if(!$mobile): ?><h2>Store pages & product features</h2><?php endif; ?><p>Shared by every Online Store theme. Catalogue, cart and payment settings keep their existing rules.</p><nav class="sf-admin-links"><a href="<?= base_url('online_store/journal').($mobile?'?screen=mobile':''); ?>">Manage journal articles</a><a href="<?= base_url('store/'.$settings->store_slug.'/contact'); ?>" target="_blank" rel="noopener">Preview contact page ↗</a><a href="<?= base_url('store/'.$settings->store_slug.'/blog'); ?>" target="_blank" rel="noopener">Preview journal ↗</a></nav>
<form method="post" action="<?= base_url('online_store/save_content_settings'); ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name(); ?>" value="<?= $this->security->get_csrf_hash(); ?>"><input type="hidden" name="editor_mobile" value="<?= $mobile?'1':''; ?>"><div class="sf-admin-grid"><div><section class="sf-admin-card"><h3>Contact page</h3><label><input type="checkbox" name="contact_enabled" value="1" <?= $page_config['contact_enabled']?'checked':''; ?>> Show contact page</label><?php foreach(['contact_heading'=>'Page heading','contact_intro'=>'Introduction','store_address'=>'Store address','store_phone'=>'Store phone','store_email'=>'Store email','business_hours'=>'Working hours — one line per day or group of days'] as $key=>$label):$value=$page_config[$key]??$settings->$key??''; ?><label for="setting-<?= $key; ?>"><?= $label; ?></label><?php if(in_array($key,['contact_intro','store_address','business_hours'])): ?><textarea id="setting-<?= $key; ?>" name="<?= $key; ?>" rows="3" maxlength="3000"><?= htmlspecialchars($value); ?></textarea><?php else: ?><input id="setting-<?= $key; ?>" name="<?= $key; ?>" value="<?= htmlspecialchars($value,ENT_QUOTES); ?>" maxlength="1500" type="<?= $key==='store_email'?'email':'text'; ?>"><?php endif;endforeach; ?><p>Messages appear in the existing Enquiries / Leads workspace when lead capture is enabled for this business. No email is sent automatically.</p></section><section class="sf-admin-card"><h3>Journal / blog</h3><label><input type="checkbox" name="blog_enabled" value="1" <?= $page_config['blog_enabled']?'checked':''; ?>> Show journal</label><?php foreach(['blog_label'=>'Navigation name','blog_heading'=>'Page heading','blog_intro'=>'Introduction'] as $key=>$label): ?><label for="setting-<?= $key; ?>"><?= $label; ?></label><input id="setting-<?= $key; ?>" name="<?= $key; ?>" value="<?= htmlspecialchars($page_config[$key],ENT_QUOTES); ?>" maxlength="1500"><?php endforeach; ?></section><section class="sf-admin-card"><h3>Privacy Policy</h3><p>A Privacy Policy link is included in every storefront footer. Edit this notice to describe your business’s actual data practices.</p><label for="privacy-heading">Policy heading</label><input id="privacy-heading" name="privacy_heading" maxlength="1500" value="<?= htmlspecialchars($page_config['privacy_heading'],ENT_QUOTES); ?>"><label for="privacy-body">Policy text</label><textarea id="privacy-body" name="privacy_body" rows="14" maxlength="30000"><?= htmlspecialchars($page_config['privacy_body']); ?></textarea><p>Blank text restores the standard storefront notice. The store’s contact details appear below the policy.</p><a href="<?= base_url('store/'.$settings->store_slug.'/privacy'); ?>" target="_blank" rel="noopener">View Privacy Policy ↗</a></section></div><aside><?php if((mp_get_store_profile()['industry_type'] ?? '')==='garden_centre_landscaping'): ?><section class="sf-admin-card"><h3>Garden product page tools</h3><?php foreach(['buy_now'=>'Buy now — add the chosen item to the existing cart and open checkout','whatsapp_order'=>'Order via WhatsApp — requires WhatsApp ordering and a number in Store Settings','product_sharing'=>'Share links — Facebook, X, Pinterest and copy link','pickup_enabled'=>'Show pickup & store information'] as $key=>$label): ?><label><input type="checkbox" name="<?= $key; ?>" value="1" <?= $page_config[$key]?'checked':''; ?>> <?= $label; ?></label><?php endforeach; ?><label for="pickup-ready">Pickup preparation note (optional)</label><textarea id="pickup-ready" name="pickup_ready_text" rows="3" maxlength="1500" placeholder="e.g. Contact us to arrange collection"><?= htmlspecialchars($page_config['pickup_ready_text']); ?></textarea><p>Pickup uses published branch names and addresses from Branches. Confirm availability with customers; this setting does not create or reserve branch stock. Services retain booking requests.</p><a href="<?= base_url('warehouse'); ?>">Manage branch addresses ↗</a></section><?php else: ?><section class="sf-admin-card"><h3>Product ordering</h3><p>Your active theme provides its product, cart and checkout controls. Manage ordering and WhatsApp using the existing Store Settings.</p><?php foreach(['buy_now','whatsapp_order','product_sharing','pickup_enabled'] as $key): ?><input type="hidden" name="<?= $key; ?>" value="<?= !empty($page_config[$key])?'1':'0'; ?>"><?php endforeach; ?><input type="hidden" name="pickup_ready_text" value="<?= htmlspecialchars($page_config['pickup_ready_text'],ENT_QUOTES); ?>"><a href="<?= base_url('online_store/settings'); ?>">Store settings ↗</a></section><?php endif; ?><button type="submit" class="sf-admin-action">Save settings</button></aside></div></form>
